"""Deterministic ECDSA signing and verification on secp256k1.

This module implements ECDSA with RFC 6979 deterministic nonces, low-S
(canonical) signatures, public-key recovery, and both compact and DER
serialization. It relies only on the Python standard library and the internal
secp256k1 primitives shipped with libcrypto. No external cryptography package
is required.
"""
from __future__ import annotations

import hashlib
import hmac
from typing import Optional, Tuple

from .constants import SECP256K1_N, SECP256K1_P
from .secp256k1 import (
    Secp256k1Error,
    _point_add,
    _point_multiply,
    _scalar_multiply_base,
    public_key_to_point_coords,
)

_HALF_N = SECP256K1_N // 2
_ORDER_BYTES = 32  # ceil(log2(N) / 8) for secp256k1.


class SignatureError(ValueError):
    """Raised when signing, verification, or recovery fails."""


class Signature:
    """An ECDSA signature over secp256k1.

    Attributes
    ----------
    r, s:
        The signature scalars, ``1 <= r, s < N``.
    recovery_id:
        Optional public-key recovery id (0..3). Present for signatures produced
        by :func:`sign`; required for message-signature formats that embed the
        recovery byte.
    """

    __slots__ = ("r", "s", "recovery_id")

    def __init__(self, r: int, s: int, recovery_id: Optional[int] = None) -> None:
        if not (1 <= r < SECP256K1_N):
            raise SignatureError("Signature r is out of range.")
        if not (1 <= s < SECP256K1_N):
            raise SignatureError("Signature s is out of range.")
        if recovery_id is not None and recovery_id not in (0, 1, 2, 3):
            raise SignatureError("recovery_id must be one of 0, 1, 2, 3.")
        self.r = r
        self.s = s
        self.recovery_id = recovery_id

    @property
    def is_canonical(self) -> bool:
        """Return True when s is in the lower half of the curve order."""
        return self.s <= _HALF_N

    def to_compact(self) -> bytes:
        """Return the 64-byte big-endian ``r || s`` representation."""
        return self.r.to_bytes(32, "big") + self.s.to_bytes(32, "big")

    @classmethod
    def from_compact(cls, data: bytes, recovery_id: Optional[int] = None) -> "Signature":
        """Parse a 64-byte compact signature."""
        if len(data) != 64:
            raise SignatureError("Compact signature must be 64 bytes.")
        r = int.from_bytes(data[:32], "big")
        s = int.from_bytes(data[32:], "big")
        return cls(r, s, recovery_id)

    def to_der(self) -> bytes:
        """Return the strict DER encoding of the signature."""
        def encode_integer(value: int) -> bytes:
            payload = value.to_bytes((value.bit_length() + 7) // 8 or 1, "big")
            # A leading 0x00 keeps the value positive when the high bit is set.
            if payload[0] & 0x80:
                payload = b"\x00" + payload
            return b"\x02" + bytes([len(payload)]) + payload

        body = encode_integer(self.r) + encode_integer(self.s)
        return b"\x30" + bytes([len(body)]) + body

    @classmethod
    def from_der(cls, data: bytes, recovery_id: Optional[int] = None) -> "Signature":
        """Parse a DER-encoded signature."""
        if len(data) < 8 or data[0] != 0x30:
            raise SignatureError("Invalid DER signature header.")
        if data[1] != len(data) - 2:
            raise SignatureError("Invalid DER signature length.")

        index = 2
        r, index = cls._read_der_integer(data, index)
        s, index = cls._read_der_integer(data, index)
        if index != len(data):
            raise SignatureError("Trailing bytes after DER signature.")
        return cls(r, s, recovery_id)

    @staticmethod
    def _read_der_integer(data: bytes, index: int) -> Tuple[int, int]:
        if index + 2 > len(data) or data[index] != 0x02:
            raise SignatureError("Expected DER INTEGER.")
        length = data[index + 1]
        start = index + 2
        end = start + length
        if length == 0 or end > len(data):
            raise SignatureError("Invalid DER INTEGER length.")
        payload = data[start:end]
        if payload[0] & 0x80:
            raise SignatureError("Negative DER INTEGER is not allowed.")
        if len(payload) > 1 and payload[0] == 0x00 and not (payload[1] & 0x80):
            raise SignatureError("Non-minimal DER INTEGER encoding.")
        return int.from_bytes(payload, "big"), end

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Signature):
            return NotImplemented
        return self.r == other.r and self.s == other.s

    def __repr__(self) -> str:
        return f"Signature(r=0x{self.r:064x}, s=0x{self.s:064x}, recovery_id={self.recovery_id})"


def _bits2int(data: bytes, qlen: int) -> int:
    """RFC 6979 bits2int: interpret data as a big-endian integer, truncated."""
    value = int.from_bytes(data, "big")
    excess = len(data) * 8 - qlen
    if excess > 0:
        value >>= excess
    return value


def _int2octets(value: int) -> bytes:
    """RFC 6979 int2octets over the curve order."""
    return (value % SECP256K1_N).to_bytes(_ORDER_BYTES, "big")


def _bits2octets(data: bytes, qlen: int) -> bytes:
    """RFC 6979 bits2octets over the curve order."""
    z1 = _bits2int(data, qlen)
    z2 = z1 % SECP256K1_N
    return z2.to_bytes(_ORDER_BYTES, "big")


def _rfc6979_generate_k(private_key: int, message_hash: bytes, hash_cls) -> int:
    """Generate the RFC 6979 deterministic nonce k."""
    qlen = SECP256K1_N.bit_length()
    hlen = hash_cls().digest_size

    x_octets = _int2octets(private_key)
    h1_octets = _bits2octets(message_hash, qlen)

    v = b"\x01" * hlen
    k = b"\x00" * hlen

    k = hmac.new(k, v + b"\x00" + x_octets + h1_octets, hash_cls).digest()
    v = hmac.new(k, v, hash_cls).digest()
    k = hmac.new(k, v + b"\x01" + x_octets + h1_octets, hash_cls).digest()
    v = hmac.new(k, v, hash_cls).digest()

    while True:
        t = b""
        while len(t) * 8 < qlen:
            v = hmac.new(k, v, hash_cls).digest()
            t += v
        candidate = _bits2int(t, qlen)
        if 1 <= candidate < SECP256K1_N:
            return candidate
        k = hmac.new(k, v + b"\x00", hash_cls).digest()
        v = hmac.new(k, v, hash_cls).digest()


def sign(
    private_key: int,
    message_hash: bytes,
    *,
    hash_cls=hashlib.sha256,
    canonical: bool = True,
) -> Signature:
    """Create a deterministic ECDSA signature for a pre-computed message hash.

    Parameters
    ----------
    private_key:
        The signing private key as an integer in ``[1, N-1]``.
    message_hash:
        The digest to sign (for example ``sha256(...)`` or ``keccak256(...)``).
    hash_cls:
        Hash constructor used for the RFC 6979 HMAC nonce (default SHA-256).
    canonical:
        When True (default) the signature is normalized to low-S form as
        required by Bitcoin and EVM chains.
    """
    if not isinstance(private_key, int):
        raise SignatureError("Private key must be an integer.")
    if not (1 <= private_key < SECP256K1_N):
        raise SignatureError("Private key is out of the valid range (1 to N-1).")
    if not isinstance(message_hash, (bytes, bytearray)):
        raise SignatureError("message_hash must be bytes.")

    message_hash = bytes(message_hash)
    qlen = SECP256K1_N.bit_length()
    z = _bits2int(message_hash, qlen)

    while True:
        k = _rfc6979_generate_k(private_key, message_hash, hash_cls)
        point_x, point_y = _scalar_multiply_base(k)
        r = point_x % SECP256K1_N
        if r == 0:
            continue

        k_inv = pow(k, -1, SECP256K1_N)
        s = (k_inv * (z + r * private_key)) % SECP256K1_N
        if s == 0:
            continue

        recovery_id = (point_y & 1) | (2 if point_x >= SECP256K1_N else 0)

        if canonical and s > _HALF_N:
            s = SECP256K1_N - s
            recovery_id ^= 1

        return Signature(r, s, recovery_id)


def _public_key_point(public_key: bytes) -> Tuple[int, int]:
    try:
        return public_key_to_point_coords(public_key)
    except Secp256k1Error as exc:
        raise SignatureError(f"Invalid public key: {exc}") from exc


def verify(public_key: bytes, message_hash: bytes, signature: Signature) -> bool:
    """Verify an ECDSA signature against a public key and message hash."""
    if not isinstance(signature, Signature):
        raise SignatureError("signature must be a Signature instance.")
    if not isinstance(message_hash, (bytes, bytearray)):
        raise SignatureError("message_hash must be bytes.")

    r, s = signature.r, signature.s
    if not (1 <= r < SECP256K1_N and 1 <= s < SECP256K1_N):
        return False

    qx, qy = _public_key_point(public_key)
    qlen = SECP256K1_N.bit_length()
    z = _bits2int(bytes(message_hash), qlen)

    s_inv = pow(s, -1, SECP256K1_N)
    u1 = (z * s_inv) % SECP256K1_N
    u2 = (r * s_inv) % SECP256K1_N

    part1 = _scalar_multiply_base(u1) if u1 != 0 else None
    if u2 != 0:
        px, py = _point_multiply(u2, qx, qy)
        part2 = None if px is None else (px, py)
    else:
        part2 = None

    if part1 is None:
        combined = part2
    elif part2 is None:
        combined = part1
    else:
        cx, cy = _point_add(part1[0], part1[1], part2[0], part2[1])
        combined = None if cx is None else (cx, cy)

    if combined is None:
        return False

    return combined[0] % SECP256K1_N == r


def recover_public_key(
    message_hash: bytes,
    signature: Signature,
    recovery_id: Optional[int] = None,
    *,
    compressed: bool = True,
) -> bytes:
    """Recover the public key that produced a signature.

    ``recovery_id`` defaults to ``signature.recovery_id`` when omitted.
    """
    if recovery_id is None:
        recovery_id = signature.recovery_id
    if recovery_id is None or recovery_id not in (0, 1, 2, 3):
        raise SignatureError("A valid recovery_id (0..3) is required.")
    if not isinstance(message_hash, (bytes, bytearray)):
        raise SignatureError("message_hash must be bytes.")

    r, s = signature.r, signature.s
    qlen = SECP256K1_N.bit_length()
    z = _bits2int(bytes(message_hash), qlen)

    # Reconstruct the x-coordinate of the nonce point R.
    x = r + (recovery_id >> 1) * SECP256K1_N
    if x >= SECP256K1_P:
        raise SignatureError("Recovered x-coordinate is not on the curve field.")

    prefix = b"\x02" if (recovery_id & 1) == 0 else b"\x03"
    r_point = _public_key_point(prefix + x.to_bytes(32, "big"))

    r_inv = pow(r, -1, SECP256K1_N)
    u1 = (-z * r_inv) % SECP256K1_N
    u2 = (s * r_inv) % SECP256K1_N

    part1 = _scalar_multiply_base(u1) if u1 != 0 else None
    if u2 != 0:
        px, py = _point_multiply(u2, r_point[0], r_point[1])
        part2 = None if px is None else (px, py)
    else:
        part2 = None

    if part1 is None:
        result = part2
    elif part2 is None:
        result = part1
    else:
        cx, cy = _point_add(part1[0], part1[1], part2[0], part2[1])
        result = None if cx is None else (cx, cy)

    if result is None:
        raise SignatureError("Public key recovery produced the point at infinity.")

    qx, qy = result
    if compressed:
        prefix = b"\x02" if qy % 2 == 0 else b"\x03"
        return prefix + qx.to_bytes(32, "big")
    return b"\x04" + qx.to_bytes(32, "big") + qy.to_bytes(32, "big")


__all__ = [
    "Signature",
    "SignatureError",
    "sign",
    "verify",
    "recover_public_key",
]
